def latMin = 24 def latMax = 49 def lonMin = -125 def lonMax = -66 def step = 2
def state = context.stateManager.getState(org.apache.nifi.components.state.Scope.LOCAL) def lat = state.get("lat")?.toDouble() ?: latMin def lon = state.get("lon")?.toDouble() ?: lonMin
def nextLat = lat def nextLon = lon + step
if (nextLon > lonMax) { nextLon = lonMin nextLat = lat + step }
if (nextLat > latMax) { nextLat = latMin nextLon = lonMin }
def flowFile = session.create() flowFile = session.putAttribute(flowFile, "lat", lat.toString()) flowFile = session.putAttribute(flowFile, "lon", lon.toString())
context.stateManager.setState( ["lat": nextLat.toString(), "lon": nextLon.toString()], org.apache.nifi.components.state.Scope.LOCAL )
session.transfer(flowFile, REL_SUCCESS)
